#include "ksPanelActionTask.h"
#include <stdexcept>
#include <iostream>
#include <vector>
#include <tuple>
int main(){using T=ks::PanelActionTask;using S=T::Stage;using C=T::Child;using Event=std::tuple<C,unsigned>;unsigned cases=0;for(unsigned kind=0;kind<10;++kind)for(unsigned input=0;input<256;++input)for(unsigned count:{0u,1u,2u,20u,255u})for(unsigned reply:{0u,20u,127u}){T t(static_cast<T::Kind>(kind));std::vector<Event>events;while(t.stage()!=S::Complete){auto child=t.child();if(child!=C::None){if(child!=C::Poll&&child!=C::DataRead)events.emplace_back(child,child==C::Spaces?t.remaining():t.input());else events.emplace_back(child,0);if(!t.resumeChild(uint8_t(reply)))throw std::runtime_error("resume");continue;}auto cost=t.nextClocks();if(t.advanceBefore(cost-1,[](T::Read){return 0;}))throw std::runtime_error("early");t.advanceBefore(cost,[&](T::Read r){return r==T::Read::Input?input:count;});}std::vector<Event>expected;switch(kind){case 0:expected={{C::Poll,0},{C::CommandByte,input}};break;case 1:expected={{C::Poll,0},{C::DataRead,0}};if(t.reply()!=reply)throw std::runtime_error("reply");break;case 2:expected={{C::Poll,0}};if(reply==20){expected.emplace_back(C::CommandByte,0xc0);expected.emplace_back(C::Poll,0);}expected.emplace_back(C::DataByte,input);break;case 3:expected={{C::Command,0x38},{C::Command,0xc},{C::Command,1}};break;case 4:expected={{C::Command,uint8_t(input+128)}};break;case 5:for(unsigned n=0;n<(count?count:256);++n)expected.emplace_back(C::Write,0x20);break;case 6:case 7:expected={{C::Cursor,kind==6?0:0x40},{C::Spaces,20},{C::Cursor,kind==6?0:0x40}};break;case 8:expected={{C::Command,uint8_t(input+64)}};break;case 9:expected={{C::Poll,0},{C::DataByte,input}};break;}if(events!=expected)throw std::runtime_error("action events/values/order");++cases;}std::cout<<"PASS: "<<cases<<" pure panel-action properties\n";}
